SELECT FROM todo WHERE user_id = #{userId} AND deleted = 0
AND status = #{status}
ORDER BY CASE status WHEN 0 THEN 0 WHEN 1 THEN 1 WHEN 3 THEN 2 ELSE 3 END, deadline IS NULL, deadline ASC, id DESC

mapper.update:
UPDATE todo
SET deleted = 1, update_time = NOW()
WHERE id = #{id} AND user_id = #{userId}
